def run_with_timeout(func, args=(), kwargs={}, timeout=5):
    result = [None]
    exception = [None]

    def target():
        try:
            result[0] = func(*args, **kwargs)
        except Exception as e:
            exception[0] = e

    thread = threading.Thread(target=target)
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        thread._stop()  # This is a non-standard method to stop a thread
        raise TimeoutError("Operation timed out")
    elif exception[0]:
        raise exception[0]
    else:
        return result[0]

